25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * UDP ethernet frame receiver (IP frame in, UDP frame out)
33	 */
34	module udp_ip_rx
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	
39	    /*
40	     * IP frame input
41	     */
42	    input  wire        s_ip_hdr_valid,
43	    output wire        s_ip_hdr_ready,
44	    input  wire [47:0] s_eth_dest_mac,
45	    input  wire [47:0] s_eth_src_mac,
46	    input  wire [15:0] s_eth_type,
47	    input  wire [3:0]  s_ip_version,
48	    input  wire [3:0]  s_ip_ihl,
49	    input  wire [5:0]  s_ip_dscp,
50	    input  wire [1:0]  s_ip_ecn,
51	    input  wire [15:0] s_ip_length,
52	    input  wire [15:0] s_ip_identification,
53	    input  wire [2:0]  s_ip_flags,
54	    input  wire [12:0] s_ip_fragment_offset,
55	    input  wire [7:0]  s_ip_ttl,
56	    input  wire [7:0]  s_ip_protocol,
57	    input  wire [15:0] s_ip_header_checksum,
58	    input  wire [31:0] s_ip_source_ip,
59	    input  wire [31:0] s_ip_dest_ip,
60	    input  wire [7:0]  s_ip_payload_axis_tdata,
61	    input  wire        s_ip_payload_axis_tvalid,
62	    output wire        s_ip_payload_axis_tready,
63	    input  wire        s_ip_payload_axis_tlast,
64	    input  wire        s_ip_payload_axis_tuser,
65	
66	    /*
67	     * UDP frame output
68	     */
69	    output wire        m_udp_hdr_valid,
70	    input  wire        m_udp_hdr_ready,
71	    output wire [47:0] m_eth_dest_mac,
72	    output wire [47:0] m_eth_src_mac,
73	    output wire [15:0] m_eth_type,
74	    output wire [3:0]  m_ip_version,
75	    output wire [3:0]  m_ip_ihl,
76	    output wire [5:0]  m_ip_dscp,
77	    output wire [1:0]  m_ip_ecn,
78	    output wire [15:0] m_ip_length,
79	    output wire [15:0] m_ip_identification,
80	    output wire [2:0]  m_ip_flags,
81	    output wire [12:0] m_ip_fragment_offset,
82	    output wire [7:0]  m_ip_ttl,
83	    output wire [7:0]  m_ip_protocol,
84	    output wire [15:0] m_ip_header_checksum,
85	    output wire [31:0] m_ip_source_ip,
86	    output wire [31:0] m_ip_dest_ip,
87	    output wire [15:0] m_udp_source_port,
88	    output wire [15:0] m_udp_dest_port,
89	    output wire [15:0] m_udp_length,
90	    output wire [15:0] m_udp_checksum,
91	    output wire [7:0]  m_udp_payload_axis_tdata,
92	    output wire        m_udp_payload_axis_tvalid,
93	    input  wire        m_udp_payload_axis_tready,
94	    output wire        m_udp_payload_axis_tlast,
95	    output wire        m_udp_payload_axis_tuser,
96	
97	    /*
98	     * Status signals
99	     */
100	    output wire        busy,
101	    output wire        error_header_early_termination,
102	    output wire        error_payload_early_termination
103	);
104	
105	/*
106	
107	UDP Frame
108	
109	 Field                       Length
110	 Destination MAC address     6 octets
111	 Source MAC address          6 octets
112	 Ethertype (0x0800)          2 octets
113	 Version (4)                 4 bits
114	 IHL (5-15)                  4 bits
115	 DSCP (0)                    6 bits
116	 ECN (0)                     2 bits
117	 length                      2 octets
118	 identification (0?)         2 octets
119	 flags (010)                 3 bits
120	 fragment offset (0)         13 bits
121	 time to live (64?)          1 octet
122	 protocol                    1 octet
123	 header checksum             2 octets
124	 source IP                   4 octets
125	 destination IP              4 octets
126	 options                     (IHL-5)*4 octets
127	
128	 source port                 2 octets
129	 desination port             2 octets
130	 length                      2 octets
131	 checksum                    2 octets
132	
133	 payload                     length octets
134	
135	This module receives an IP frame with header fields in parallel and payload on
136	an AXI stream interface, decodes and strips the UDP header fields, then
137	produces the header fields in parallel along with the UDP payload in a
138	separate AXI stream.
139	
140	*/
141	
142	localparam [2:0]
143	    STATE_IDLE = 3'd0,
144	    STATE_READ_HEADER = 3'd1,
145	    STATE_READ_PAYLOAD = 3'd2,
146	    STATE_READ_PAYLOAD_LAST = 3'd3,
147	    STATE_WAIT_LAST = 3'd4;
148	
149	reg [2:0] state_reg = STATE_IDLE, state_next;
150	
151	// datapath control signals
152	reg store_ip_hdr;
153	reg store_udp_source_port_0;
154	reg store_udp_source_port_1;
155	reg store_udp_dest_port_0;
156	reg store_udp_dest_port_1;
157	reg store_udp_length_0;
158	reg store_udp_length_1;
159	reg store_udp_checksum_0;
160	reg store_udp_checksum_1;
161	reg store_last_word;
162	
163	reg [2:0] hdr_ptr_reg = 3'd0, hdr_ptr_next;
164	reg [15:0] word_count_reg = 16'd0, word_count_next;
165	
166	reg [7:0] last_word_data_reg = 8'd0;
167	
168	reg m_udp_hdr_valid_reg = 1'b0, m_udp_hdr_valid_next;
169	reg [47:0] m_eth_dest_mac_reg = 48'd0;
170	reg [47:0] m_eth_src_mac_reg = 48'd0;
171	reg [15:0] m_eth_type_reg = 16'd0;
172	reg [3:0] m_ip_version_reg = 4'd0;
173	reg [3:0] m_ip_ihl_reg = 4'd0;
174	reg [5:0] m_ip_dscp_reg = 6'd0;
175	reg [1:0] m_ip_ecn_reg = 2'd0;
176	reg [15:0] m_ip_length_reg = 16'd0;
177	reg [15:0] m_ip_identification_reg = 16'd0;
178	reg [2:0] m_ip_flags_reg = 3'd0;
179	reg [12:0] m_ip_fragment_offset_reg = 13'd0;
180	reg [7:0] m_ip_ttl_reg = 8'd0;
181	reg [7:0] m_ip_protocol_reg = 8'd0;
182	reg [15:0] m_ip_header_checksum_reg = 16'd0;
183	reg [31:0] m_ip_source_ip_reg = 32'd0;
184	reg [31:0] m_ip_dest_ip_reg = 32'd0;
185	reg [15:0] m_udp_source_port_reg = 16'd0;
186	reg [15:0] m_udp_dest_port_reg = 16'd0;
187	reg [15:0] m_udp_length_reg = 16'd0;
188	reg [15:0] m_udp_checksum_reg = 16'd0;
189	
190	reg s_ip_hdr_ready_reg = 1'b0, s_ip_hdr_ready_next;
191	reg s_ip_payload_axis_tready_reg = 1'b0, s_ip_payload_axis_tready_next;
192	
193	reg busy_reg = 1'b0;
194	reg error_header_early_termination_reg = 1'b0, error_header_early_termination_next;
195	reg error_payload_early_termination_reg = 1'b0, error_payload_early_termination_next;
196	
197	// internal datapath
198	reg [7:0] m_udp_payload_axis_tdata_int;
199	reg       m_udp_payload_axis_tvalid_int;
200	reg       m_udp_payload_axis_tready_int_reg = 1'b0;
201	reg       m_udp_payload_axis_tlast_int;
202	reg       m_udp_payload_axis_tuser_int;
203	wire      m_udp_payload_axis_tready_int_early;
204	
205	assign s_ip_hdr_ready = s_ip_hdr_ready_reg;
206	assign s_ip_payload_axis_tready = s_ip_payload_axis_tready_reg;
207	
208	assign m_udp_hdr_valid = m_udp_hdr_valid_reg;
209	assign m_eth_dest_mac = m_eth_dest_mac_reg;
210	assign m_eth_src_mac = m_eth_src_mac_reg;
211	assign m_eth_type = m_eth_type_reg;
212	assign m_ip_version = m_ip_version_reg;
213	assign m_ip_ihl = m_ip_ihl_reg;
214	assign m_ip_dscp = m_ip_dscp_reg;
215	assign m_ip_ecn = m_ip_ecn_reg;
216	assign m_ip_length = m_ip_length_reg;
217	assign m_ip_identification = m_ip_identification_reg;
218	assign m_ip_flags = m_ip_flags_reg;
219	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
220	assign m_ip_ttl = m_ip_ttl_reg;
221	assign m_ip_protocol = m_ip_protocol_reg;
222	assign m_ip_header_checksum = m_ip_header_checksum_reg;
223	assign m_ip_source_ip = m_ip_source_ip_reg;
224	assign m_ip_dest_ip = m_ip_dest_ip_reg;
225	assign m_udp_source_port = m_udp_source_port_reg;
226	assign m_udp_dest_port = m_udp_dest_port_reg;
227	assign m_udp_length = m_udp_length_reg;
228	assign m_udp_checksum = m_udp_checksum_reg;
229	
230	assign busy = busy_reg;
231	assign error_header_early_termination = error_header_early_termination_reg;
232	assign error_payload_early_termination = error_payload_early_termination_reg;
233	
234	always @* begin
235	    state_next = STATE_IDLE;
236	
237	    s_ip_hdr_ready_next = 1'b0;
238	    s_ip_payload_axis_tready_next = 1'b0;
239	
240	    store_ip_hdr = 1'b0;
241	    store_udp_source_port_0 = 1'b0;
242	    store_udp_source_port_1 = 1'b0;
243	    store_udp_dest_port_0 = 1'b0;
244	    store_udp_dest_port_1 = 1'b0;
245	    store_udp_length_0 = 1'b0;
246	    store_udp_length_1 = 1'b0;
247	    store_udp_checksum_0 = 1'b0;
248	    store_udp_checksum_1 = 1'b0;
249	
250	    store_last_word = 1'b0;
251	
252	    hdr_ptr_next = hdr_ptr_reg;
253	    word_count_next = word_count_reg;
254	
255	    m_udp_hdr_valid_next = m_udp_hdr_valid_reg && !m_udp_hdr_ready;
256	
257	    error_header_early_termination_next = 1'b0;
258	    error_payload_early_termination_next = 1'b0;
259	
260	    m_udp_payload_axis_tdata_int = 8'd0;
261	    m_udp_payload_axis_tvalid_int = 1'b0;
262	    m_udp_payload_axis_tlast_int = 1'b0;
263	    m_udp_payload_axis_tuser_int = 1'b0;
264	
265	    case (state_reg)
266	        STATE_IDLE: begin
267	            // idle state - wait for header
268	            hdr_ptr_next = 3'd0;
269	            s_ip_hdr_ready_next = !m_udp_hdr_valid_next;
270	
271	            if (s_ip_hdr_ready && s_ip_hdr_valid) begin
272	                s_ip_hdr_ready_next = 1'b0;
273	                s_ip_payload_axis_tready_next = 1'b1;
274	                store_ip_hdr = 1'b1;
275	                state_next = STATE_READ_HEADER;
276	            end else begin
277	                state_next = STATE_IDLE;
278	            end
279	        end
280	        STATE_READ_HEADER: begin
281	            // read header state
282	            s_ip_payload_axis_tready_next = 1'b1;
283	            word_count_next = m_udp_length_reg - 16'd8;
284	
285	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
286	                // word transfer in - store it
287	                hdr_ptr_next = hdr_ptr_reg + 3'd1;
288	                state_next = STATE_READ_HEADER;
289	
290	                case (hdr_ptr_reg)
291	                    3'h0: store_udp_source_port_1 = 1'b1;
292	                    3'h1: store_udp_source_port_0 = 1'b1;
293	                    3'h2: store_udp_dest_port_1 = 1'b1;
294	                    3'h3: store_udp_dest_port_0 = 1'b1;
295	                    3'h4: store_udp_length_1 = 1'b1;
296	                    3'h5: store_udp_length_0 = 1'b1;
297	                    3'h6: store_udp_checksum_1 = 1'b1;
298	                    3'h7: begin
299	                        store_udp_checksum_0 = 1'b1;
300	                        m_udp_hdr_valid_next = 1'b1;
301	                        s_ip_payload_axis_tready_next = m_udp_payload_axis_tready_int_early;
302	                        state_next = STATE_READ_PAYLOAD;
303	                    end
304	                endcase
305	
306	                if (s_ip_payload_axis_tlast) begin
307	                    error_header_early_termination_next = 1'b1;
308	                    m_udp_hdr_valid_next = 1'b0;
309	                    s_ip_hdr_ready_next = !m_udp_hdr_valid_next;
310	                    s_ip_payload_axis_tready_next = 1'b0;
311	                    state_next = STATE_IDLE;
312	                end
313	
314	            end else begin
315	                state_next = STATE_READ_HEADER;
316	            end
317	        end
318	        STATE_READ_PAYLOAD: begin
319	            // read payload
320	            s_ip_payload_axis_tready_next = m_udp_payload_axis_tready_int_early;
321	
322	            m_udp_payload_axis_tdata_int = s_ip_payload_axis_tdata;
323	            m_udp_payload_axis_tlast_int = s_ip_payload_axis_tlast;
324	            m_udp_payload_axis_tuser_int = s_ip_payload_axis_tuser;
325	
326	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
327	                // word transfer through
328	                word_count_next = word_count_reg - 16'd1;
329	                m_udp_payload_axis_tvalid_int = 1'b1;
330	                if (s_ip_payload_axis_tlast) begin
331	                    if (word_count_reg != 16'd1) begin
332	                        // end of frame, but length does not match
333	                        m_udp_payload_axis_tuser_int = 1'b1;
334	                        error_payload_early_termination_next = 1'b1;
335	                    end
336	                    s_ip_hdr_ready_next = !m_udp_hdr_valid_next;
337	                    s_ip_payload_axis_tready_next = 1'b0;
338	                    state_next = STATE_IDLE;
339	                end else begin
340	                    if (word_count_reg == 16'd1) begin
341	                        store_last_word = 1'b1;
342	                        m_udp_payload_axis_tvalid_int = 1'b0;
343	                        state_next = STATE_READ_PAYLOAD_LAST;
344	                    end else begin
345	                        state_next = STATE_READ_PAYLOAD;
346	                    end
347	                end
348	            end else begin
349	                state_next = STATE_READ_PAYLOAD;
350	            end
351	        end
352	        STATE_READ_PAYLOAD_LAST: begin
353	            // read and discard until end of frame
354	            s_ip_payload_axis_tready_next = m_udp_payload_axis_tready_int_early;
355	
356	            m_udp_payload_axis_tdata_int = last_word_data_reg;
357	            m_udp_payload_axis_tlast_int = s_ip_payload_axis_tlast;
358	            m_udp_payload_axis_tuser_int = s_ip_payload_axis_tuser;
359	
360	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
361	                if (s_ip_payload_axis_tlast) begin
362	                    s_ip_hdr_ready_next = !m_udp_hdr_valid_next;
363	                    s_ip_payload_axis_tready_next = 1'b0;
364	                    m_udp_payload_axis_tvalid_int = 1'b1;
365	                    state_next = STATE_IDLE;
366	                end else begin
367	                    state_next = STATE_READ_PAYLOAD_LAST;
368	                end
369	            end else begin
370	                state_next = STATE_READ_PAYLOAD_LAST;
371	            end
372	        end
373	        STATE_WAIT_LAST: begin
374	            // wait for end of frame; read and discard
375	            s_ip_payload_axis_tready_next = 1'b1;
376	
377	            if (s_ip_payload_axis_tready && s_ip_payload_axis_tvalid) begin
378	                if (s_ip_payload_axis_tlast) begin
379	                    s_ip_hdr_ready_next = !m_udp_hdr_valid_next;
380	                    s_ip_payload_axis_tready_next = 1'b0;
381	                    state_next = STATE_IDLE;
382	                end else begin
383	                    state_next = STATE_WAIT_LAST;
384	                end
385	            end else begin
386	                state_next = STATE_WAIT_LAST;
387	            end
388	        end
389	    endcase
390	end
391	
392	always @(posedge clk) begin
393	    if (rst) begin
394	        state_reg <= STATE_IDLE;
395	        s_ip_hdr_ready_reg <= 1'b0;
396	        s_ip_payload_axis_tready_reg <= 1'b0;
397	        m_udp_hdr_valid_reg <= 1'b0;
398	        busy_reg <= 1'b0;
399	        error_header_early_termination_reg <= 1'b0;
400	        error_payload_early_termination_reg <= 1'b0;
401	    end else begin
402	        state_reg <= state_next;
403	
404	
405	        s_ip_hdr_ready_reg <= s_ip_hdr_ready_next;
406	        s_ip_payload_axis_tready_reg <= s_ip_payload_axis_tready_next;
407	
408	        m_udp_hdr_valid_reg <= m_udp_hdr_valid_next;
409	
410	        error_header_early_termination_reg <= error_header_early_termination_next;
411	        error_payload_early_termination_reg <= error_payload_early_termination_next;
412	
413	        busy_reg <= state_next != STATE_IDLE;
414	    end
415	
416	    hdr_ptr_reg <= hdr_ptr_next;
417	    word_count_reg <= word_count_next;
418	
419	    // datapath
420	    if (store_ip_hdr) begin
421	        m_eth_dest_mac_reg <= s_eth_dest_mac;
422	        m_eth_src_mac_reg <= s_eth_src_mac;
423	        m_eth_type_reg <= s_eth_type;
424	        m_ip_version_reg <= s_ip_version;
425	        m_ip_ihl_reg <= s_ip_ihl;
426	        m_ip_dscp_reg <= s_ip_dscp;
427	        m_ip_ecn_reg <= s_ip_ecn;
428	        m_ip_length_reg <= s_ip_length;
429	        m_ip_identification_reg <= s_ip_identification;
430	        m_ip_flags_reg <= s_ip_flags;
431	        m_ip_fragment_offset_reg <= s_ip_fragment_offset;
432	        m_ip_ttl_reg <= s_ip_ttl;
433	        m_ip_protocol_reg <= s_ip_protocol;
434	        m_ip_header_checksum_reg <= s_ip_header_checksum;
435	        m_ip_source_ip_reg <= s_ip_source_ip;
436	        m_ip_dest_ip_reg <= s_ip_dest_ip;
437	    end
438	
439	    if (store_last_word) begin
440	        last_word_data_reg <= m_udp_payload_axis_tdata_int;
441	    end
442	
443	    if (store_udp_source_port_0) m_udp_source_port_reg[ 7: 0] <= s_ip_payload_axis_tdata;
444	    if (store_udp_source_port_1) m_udp_source_port_reg[15: 8] <= s_ip_payload_axis_tdata;
445	    if (store_udp_dest_port_0) m_udp_dest_port_reg[ 7: 0] <= s_ip_payload_axis_tdata;
446	    if (store_udp_dest_port_1) m_udp_dest_port_reg[15: 8] <= s_ip_payload_axis_tdata;
447	    if (store_udp_length_0) m_udp_length_reg[ 7: 0] <= s_ip_payload_axis_tdata;
448	    if (store_udp_length_1) m_udp_length_reg[15: 8] <= s_ip_payload_axis_tdata;
449	    if (store_udp_checksum_0) m_udp_checksum_reg[ 7: 0] <= s_ip_payload_axis_tdata;
450	    if (store_udp_checksum_1) m_udp_checksum_reg[15: 8] <= s_ip_payload_axis_tdata;
451	end
452	
453	// output datapath logic
454	reg [7:0] m_udp_payload_axis_tdata_reg = 8'd0;
455	reg       m_udp_payload_axis_tvalid_reg = 1'b0, m_udp_payload_axis_tvalid_next;
456	reg       m_udp_payload_axis_tlast_reg = 1'b0;
457	reg       m_udp_payload_axis_tuser_reg = 1'b0;
458	
459	reg [7:0] temp_m_udp_payload_axis_tdata_reg = 8'd0;
460	reg       temp_m_udp_payload_axis_tvalid_reg = 1'b0, temp_m_udp_payload_axis_tvalid_next;
461	reg       temp_m_udp_payload_axis_tlast_reg = 1'b0;
462	reg       temp_m_udp_payload_axis_tuser_reg = 1'b0;
463	
464	// datapath control
465	reg store_udp_payload_int_to_output;
466	reg store_udp_payload_int_to_temp;
467	reg store_udp_payload_axis_temp_to_output;
468	
469	assign m_udp_payload_axis_tdata = m_udp_payload_axis_tdata_reg;
470	assign m_udp_payload_axis_tvalid = m_udp_payload_axis_tvalid_reg;
471	assign m_udp_payload_axis_tlast = m_udp_payload_axis_tlast_reg;
472	assign m_udp_payload_axis_tuser = m_udp_payload_axis_tuser_reg;
473	
474	// enable ready input next cycle if output is ready or if both output registers are empty
475	assign m_udp_payload_axis_tready_int_early = m_udp_payload_axis_tready || (!temp_m_udp_payload_axis_tvalid_reg && !m_udp_payload_axis_tvalid_reg);
476	
477	always @* begin
478	    // transfer sink ready state to source
479	    m_udp_payload_axis_tvalid_next = m_udp_payload_axis_tvalid_reg;
480	    temp_m_udp_payload_axis_tvalid_next = temp_m_udp_payload_axis_tvalid_reg;
481	
482	    store_udp_payload_int_to_output = 1'b0;
483	    store_udp_payload_int_to_temp = 1'b0;
484	    store_udp_payload_axis_temp_to_output = 1'b0;
485	    
486	    if (m_udp_payload_axis_tready_int_reg) begin
487	        // input is ready
488	        if (m_udp_payload_axis_tready || !m_udp_payload_axis_tvalid_reg) begin
489	            // output is ready or currently not valid, transfer data to output
490	            m_udp_payload_axis_tvalid_next = m_udp_payload_axis_tvalid_int;
491	            store_udp_payload_int_to_output = 1'b1;
492	        end else begin
493	            // output is not ready, store input in temp
494	            temp_m_udp_payload_axis_tvalid_next = m_udp_payload_axis_tvalid_int;
495	            store_udp_payload_int_to_temp = 1'b1;
496	        end
497	    end else if (m_udp_payload_axis_tready) begin
498	        // input is not ready, but output is ready
499	        m_udp_payload_axis_tvalid_next = temp_m_udp_payload_axis_tvalid_reg;
500	        temp_m_udp_payload_axis_tvalid_next = 1'b0;
501	        store_udp_payload_axis_temp_to_output = 1'b1;
502	    end
503	end
504	
505	always @(posedge clk) begin
506	    m_udp_payload_axis_tvalid_reg <= m_udp_payload_axis_tvalid_next;
507	    m_udp_payload_axis_tready_int_reg <= m_udp_payload_axis_tready_int_early;
508	    temp_m_udp_payload_axis_tvalid_reg <= temp_m_udp_payload_axis_tvalid_next;
509	
510	    // datapath
511	    if (store_udp_payload_int_to_output) begin
512	        m_udp_payload_axis_tdata_reg <= m_udp_payload_axis_tdata_int;
513	        m_udp_payload_axis_tlast_reg <= m_udp_payload_axis_tlast_int;
514	        m_udp_payload_axis_tuser_reg <= m_udp_payload_axis_tuser_int;
515	    end else if (store_udp_payload_axis_temp_to_output) begin
516	        m_udp_payload_axis_tdata_reg <= temp_m_udp_payload_axis_tdata_reg;
517	        m_udp_payload_axis_tlast_reg <= temp_m_udp_payload_axis_tlast_reg;
518	        m_udp_payload_axis_tuser_reg <= temp_m_udp_payload_axis_tuser_reg;
519	    end
520	
521	    if (store_udp_payload_int_to_temp) begin
522	        temp_m_udp_payload_axis_tdata_reg <= m_udp_payload_axis_tdata_int;
523	        temp_m_udp_payload_axis_tlast_reg <= m_udp_payload_axis_tlast_int;
524	        temp_m_udp_payload_axis_tuser_reg <= m_udp_payload_axis_tuser_int;
525	    end
526	
527	    if (rst) begin
528	        m_udp_payload_axis_tvalid_reg <= 1'b0;
529	        m_udp_payload_axis_tready_int_reg <= 1'b0;
530	        temp_m_udp_payload_axis_tvalid_reg <= 1'b0;
531	    end
532	end
533	
534	endmodule
535	
536	`resetall
