25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * UDP ethernet frame transmitter (UDP frame in, IP frame out)
33	 */
34	module udp_ip_tx
35	(
36	    input  wire        clk,
37	    input  wire        rst,
38	
39	    /*
40	     * UDP frame input
41	     */
42	    input  wire        s_udp_hdr_valid,
43	    output wire        s_udp_hdr_ready,
44	    input  wire [47:0] s_eth_dest_mac,
45	    input  wire [47:0] s_eth_src_mac,
46	    input  wire [15:0] s_eth_type,
47	    input  wire [3:0]  s_ip_version,
48	    input  wire [3:0]  s_ip_ihl,
49	    input  wire [5:0]  s_ip_dscp,
50	    input  wire [1:0]  s_ip_ecn,
51	    input  wire [15:0] s_ip_identification,
52	    input  wire [2:0]  s_ip_flags,
53	    input  wire [12:0] s_ip_fragment_offset,
54	    input  wire [7:0]  s_ip_ttl,
55	    input  wire [7:0]  s_ip_protocol,
56	    input  wire [15:0] s_ip_header_checksum,
57	    input  wire [31:0] s_ip_source_ip,
58	    input  wire [31:0] s_ip_dest_ip,
59	    input  wire [15:0] s_udp_source_port,
60	    input  wire [15:0] s_udp_dest_port,
61	    input  wire [15:0] s_udp_length,
62	    input  wire [15:0] s_udp_checksum,
63	    input  wire [7:0]  s_udp_payload_axis_tdata,
64	    input  wire        s_udp_payload_axis_tvalid,
65	    output wire        s_udp_payload_axis_tready,
66	    input  wire        s_udp_payload_axis_tlast,
67	    input  wire        s_udp_payload_axis_tuser,
68	
69	    /*
70	     * IP frame output
71	     */
72	    output wire        m_ip_hdr_valid,
73	    input  wire        m_ip_hdr_ready,
74	    output wire [47:0] m_eth_dest_mac,
75	    output wire [47:0] m_eth_src_mac,
76	    output wire [15:0] m_eth_type,
77	    output wire [3:0]  m_ip_version,
78	    output wire [3:0]  m_ip_ihl,
79	    output wire [5:0]  m_ip_dscp,
80	    output wire [1:0]  m_ip_ecn,
81	    output wire [15:0] m_ip_length,
82	    output wire [15:0] m_ip_identification,
83	    output wire [2:0]  m_ip_flags,
84	    output wire [12:0] m_ip_fragment_offset,
85	    output wire [7:0]  m_ip_ttl,
86	    output wire [7:0]  m_ip_protocol,
87	    output wire [15:0] m_ip_header_checksum,
88	    output wire [31:0] m_ip_source_ip,
89	    output wire [31:0] m_ip_dest_ip,
90	    output wire [7:0]  m_ip_payload_axis_tdata,
91	    output wire        m_ip_payload_axis_tvalid,
92	    input  wire        m_ip_payload_axis_tready,
93	    output wire        m_ip_payload_axis_tlast,
94	    output wire        m_ip_payload_axis_tuser,
95	
96	    /*
97	     * Status signals
98	     */
99	    output wire        busy,
100	    output wire        error_payload_early_termination
101	);
102	
103	/*
104	
105	UDP Frame
106	
107	 Field                       Length
108	 Destination MAC address     6 octets
109	 Source MAC address          6 octets
110	 Ethertype (0x0800)          2 octets
111	 Version (4)                 4 bits
112	 IHL (5-15)                  4 bits
113	 DSCP (0)                    6 bits
114	 ECN (0)                     2 bits
115	 length                      2 octets
116	 identification (0?)         2 octets
117	 flags (010)                 3 bits
118	 fragment offset (0)         13 bits
119	 time to live (64?)          1 octet
120	 protocol                    1 octet
121	 header checksum             2 octets
122	 source IP                   4 octets
123	 destination IP              4 octets
124	 options                     (IHL-5)*4 octets
125	
126	 source port                 2 octets
127	 desination port             2 octets
128	 length                      2 octets
129	 checksum                    2 octets
130	
131	 payload                     length octets
132	
133	This module receives a UDP frame with header fields in parallel along with the
134	payload in an AXI stream, combines the header with the payload, passes through
135	the IP headers, and transmits the complete IP payload on an AXI interface.
136	
137	*/
138	
139	localparam [2:0]
140	    STATE_IDLE = 3'd0,
141	    STATE_WRITE_HEADER = 3'd1,
142	    STATE_WRITE_PAYLOAD = 3'd2,
143	    STATE_WRITE_PAYLOAD_LAST = 3'd3,
144	    STATE_WAIT_LAST = 3'd4;
145	
146	reg [2:0] state_reg = STATE_IDLE, state_next;
147	
148	// datapath control signals
149	reg store_udp_hdr;
150	reg store_last_word;
151	
152	reg [2:0] hdr_ptr_reg = 3'd0, hdr_ptr_next;
153	reg [15:0] word_count_reg = 16'd0, word_count_next;
154	
155	reg [7:0] last_word_data_reg = 8'd0;
156	
157	reg [15:0] udp_source_port_reg = 16'd0;
158	reg [15:0] udp_dest_port_reg = 16'd0;
159	reg [15:0] udp_length_reg = 16'd0;
160	reg [15:0] udp_checksum_reg = 16'd0;
161	
162	reg s_udp_hdr_ready_reg = 1'b0, s_udp_hdr_ready_next;
163	reg s_udp_payload_axis_tready_reg = 1'b0, s_udp_payload_axis_tready_next;
164	
165	reg m_ip_hdr_valid_reg = 1'b0, m_ip_hdr_valid_next;
166	reg [47:0] m_eth_dest_mac_reg = 48'd0;
167	reg [47:0] m_eth_src_mac_reg = 48'd0;
168	reg [15:0] m_eth_type_reg = 16'd0;
169	reg [3:0] m_ip_version_reg = 4'd0;
170	reg [3:0] m_ip_ihl_reg = 4'd0;
171	reg [5:0] m_ip_dscp_reg = 6'd0;
172	reg [1:0] m_ip_ecn_reg = 2'd0;
173	reg [15:0] m_ip_length_reg = 16'd0;
174	reg [15:0] m_ip_identification_reg = 16'd0;
175	reg [2:0] m_ip_flags_reg = 3'd0;
176	reg [12:0] m_ip_fragment_offset_reg = 13'd0;
177	reg [7:0] m_ip_ttl_reg = 8'd0;
178	reg [7:0] m_ip_protocol_reg = 8'd0;
179	reg [15:0] m_ip_header_checksum_reg = 16'd0;
180	reg [31:0] m_ip_source_ip_reg = 32'd0;
181	reg [31:0] m_ip_dest_ip_reg = 32'd0;
182	
183	reg busy_reg = 1'b0;
184	reg error_payload_early_termination_reg = 1'b0, error_payload_early_termination_next;
185	
186	// internal datapath
187	reg [7:0] m_ip_payload_axis_tdata_int;
188	reg       m_ip_payload_axis_tvalid_int;
189	reg       m_ip_payload_axis_tready_int_reg = 1'b0;
190	reg       m_ip_payload_axis_tlast_int;
191	reg       m_ip_payload_axis_tuser_int;
192	wire      m_ip_payload_axis_tready_int_early;
193	
194	assign s_udp_hdr_ready = s_udp_hdr_ready_reg;
195	assign s_udp_payload_axis_tready = s_udp_payload_axis_tready_reg;
196	
197	assign m_ip_hdr_valid = m_ip_hdr_valid_reg;
198	assign m_eth_dest_mac = m_eth_dest_mac_reg;
199	assign m_eth_src_mac = m_eth_src_mac_reg;
200	assign m_eth_type = m_eth_type_reg;
201	assign m_ip_version = m_ip_version_reg;
202	assign m_ip_ihl = m_ip_ihl_reg;
203	assign m_ip_dscp = m_ip_dscp_reg;
204	assign m_ip_ecn = m_ip_ecn_reg;
205	assign m_ip_length = m_ip_length_reg;
206	assign m_ip_identification = m_ip_identification_reg;
207	assign m_ip_flags = m_ip_flags_reg;
208	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
209	assign m_ip_ttl = m_ip_ttl_reg;
210	assign m_ip_protocol = m_ip_protocol_reg;
211	assign m_ip_header_checksum = m_ip_header_checksum_reg;
212	assign m_ip_source_ip = m_ip_source_ip_reg;
213	assign m_ip_dest_ip = m_ip_dest_ip_reg;
214	
215	assign busy = busy_reg;
216	assign error_payload_early_termination = error_payload_early_termination_reg;
217	
218	always @* begin
219	    state_next = STATE_IDLE;
220	
221	    s_udp_hdr_ready_next = 1'b0;
222	    s_udp_payload_axis_tready_next = 1'b0;
223	
224	    store_udp_hdr = 1'b0;
225	
226	    store_last_word = 1'b0;
227	
228	    hdr_ptr_next = hdr_ptr_reg;
229	    word_count_next = word_count_reg;
230	
231	    m_ip_hdr_valid_next = m_ip_hdr_valid_reg && !m_ip_hdr_ready;
232	
233	    error_payload_early_termination_next = 1'b0;
234	
235	    m_ip_payload_axis_tdata_int = 8'd0;
236	    m_ip_payload_axis_tvalid_int = 1'b0;
237	    m_ip_payload_axis_tlast_int = 1'b0;
238	    m_ip_payload_axis_tuser_int = 1'b0;
239	
240	    case (state_reg)
241	        STATE_IDLE: begin
242	            // idle state - wait for data
243	            hdr_ptr_next = 3'd0;
244	            s_udp_hdr_ready_next = !m_ip_hdr_valid_next;
245	
246	            if (s_udp_hdr_ready && s_udp_hdr_valid) begin
247	                store_udp_hdr = 1'b1;
248	                s_udp_hdr_ready_next = 1'b0;
249	                m_ip_hdr_valid_next = 1'b1;
250	                if (m_ip_payload_axis_tready_int_reg) begin
251	                    m_ip_payload_axis_tvalid_int = 1'b1;
252	                    m_ip_payload_axis_tdata_int = s_udp_source_port[15: 8];
253	                    hdr_ptr_next = 3'd1;
254	                end
255	                state_next = STATE_WRITE_HEADER;
256	            end else begin
257	                state_next = STATE_IDLE;
258	            end
259	        end
260	        STATE_WRITE_HEADER: begin
261	            // write header state
262	            word_count_next = udp_length_reg - 16'd8;
263	
264	            if (m_ip_payload_axis_tready_int_reg) begin
265	                // word transfer out
266	                hdr_ptr_next = hdr_ptr_reg + 3'd1;
267	                m_ip_payload_axis_tvalid_int = 1'b1;
268	                state_next = STATE_WRITE_HEADER;
269	                case (hdr_ptr_reg)
270	                    3'h0: m_ip_payload_axis_tdata_int = udp_source_port_reg[15: 8];
271	                    3'h1: m_ip_payload_axis_tdata_int = udp_source_port_reg[ 7: 0];
272	                    3'h2: m_ip_payload_axis_tdata_int = udp_dest_port_reg[15: 8];
273	                    3'h3: m_ip_payload_axis_tdata_int = udp_dest_port_reg[ 7: 0];
274	                    3'h4: m_ip_payload_axis_tdata_int = udp_length_reg[15: 8];
275	                    3'h5: m_ip_payload_axis_tdata_int = udp_length_reg[ 7: 0];
276	                    3'h6: m_ip_payload_axis_tdata_int = udp_checksum_reg[15: 8];
277	                    3'h7: begin
278	                        m_ip_payload_axis_tdata_int = udp_checksum_reg[ 7: 0];
279	                        s_udp_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
280	                        state_next = STATE_WRITE_PAYLOAD;
281	                    end
282	                endcase
283	            end else begin
284	                state_next = STATE_WRITE_HEADER;
285	            end
286	        end
287	        STATE_WRITE_PAYLOAD: begin
288	            // write payload
289	            s_udp_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
290	
291	            m_ip_payload_axis_tdata_int = s_udp_payload_axis_tdata;
292	            m_ip_payload_axis_tlast_int = s_udp_payload_axis_tlast;
293	            m_ip_payload_axis_tuser_int = s_udp_payload_axis_tuser;
294	
295	            if (s_udp_payload_axis_tready && s_udp_payload_axis_tvalid) begin
296	                // word transfer through
297	                word_count_next = word_count_reg - 16'd1;
298	                m_ip_payload_axis_tvalid_int = 1'b1;
299	                if (s_udp_payload_axis_tlast) begin
300	                    if (word_count_reg != 16'd1) begin
301	                        // end of frame, but length does not match
302	                        m_ip_payload_axis_tuser_int = 1'b1;
303	                        error_payload_early_termination_next = 1'b1;
304	                    end
305	                    s_udp_hdr_ready_next = !m_ip_hdr_valid_next;
306	                    s_udp_payload_axis_tready_next = 1'b0;
307	                    state_next = STATE_IDLE;
308	                end else begin
309	                    if (word_count_reg == 16'd1) begin
310	                        store_last_word = 1'b1;
311	                        m_ip_payload_axis_tvalid_int = 1'b0;
312	                        state_next = STATE_WRITE_PAYLOAD_LAST;
313	                    end else begin
314	                        state_next = STATE_WRITE_PAYLOAD;
315	                    end
316	                end
317	            end else begin
318	                state_next = STATE_WRITE_PAYLOAD;
319	            end
320	        end
321	        STATE_WRITE_PAYLOAD_LAST: begin
322	            // read and discard until end of frame
323	            s_udp_payload_axis_tready_next = m_ip_payload_axis_tready_int_early;
324	
325	            m_ip_payload_axis_tdata_int = last_word_data_reg;
326	            m_ip_payload_axis_tlast_int = s_udp_payload_axis_tlast;
327	            m_ip_payload_axis_tuser_int = s_udp_payload_axis_tuser;
328	
329	            if (s_udp_payload_axis_tready && s_udp_payload_axis_tvalid) begin
330	                if (s_udp_payload_axis_tlast) begin
331	                    s_udp_hdr_ready_next = !m_ip_hdr_valid_next;
332	                    s_udp_payload_axis_tready_next = 1'b0;
333	                    m_ip_payload_axis_tvalid_int = 1'b1;
334	                    state_next = STATE_IDLE;
335	                end else begin
336	                    state_next = STATE_WRITE_PAYLOAD_LAST;
337	                end
338	            end else begin
339	                state_next = STATE_WRITE_PAYLOAD_LAST;
340	            end
341	        end
342	        STATE_WAIT_LAST: begin
343	            // wait for end of frame; read and discard
344	            s_udp_payload_axis_tready_next = 1'b1;
345	
346	            if (s_udp_payload_axis_tvalid) begin
347	                if (s_udp_payload_axis_tlast) begin
348	                    s_udp_hdr_ready_next = !m_ip_hdr_valid_next;
349	                    s_udp_payload_axis_tready_next = 1'b0;
350	                    state_next = STATE_IDLE;
351	                end else begin
352	                    state_next = STATE_WAIT_LAST;
353	                end
354	            end else begin
355	                state_next = STATE_WAIT_LAST;
356	            end
357	        end
358	    endcase
359	end
360	
361	always @(posedge clk) begin
362	    if (rst) begin
363	        state_reg <= STATE_IDLE;
364	        s_udp_hdr_ready_reg <= 1'b0;
365	        s_udp_payload_axis_tready_reg <= 1'b0;
366	        m_ip_hdr_valid_reg <= 1'b0;
367	        busy_reg <= 1'b0;
368	        error_payload_early_termination_reg <= 1'b0;
369	    end else begin
370	        state_reg <= state_next;
371	
372	        s_udp_hdr_ready_reg <= s_udp_hdr_ready_next;
373	        s_udp_payload_axis_tready_reg <= s_udp_payload_axis_tready_next;
374	
375	        m_ip_hdr_valid_reg <= m_ip_hdr_valid_next;
376	
377	        busy_reg <= state_next != STATE_IDLE;
378	
379	        error_payload_early_termination_reg <= error_payload_early_termination_next;
380	    end
381	
382	    hdr_ptr_reg <= hdr_ptr_next;
383	    word_count_reg <= word_count_next;
384	
385	    // datapath
386	    if (store_udp_hdr) begin
387	        m_eth_dest_mac_reg <= s_eth_dest_mac;
388	        m_eth_src_mac_reg <= s_eth_src_mac;
389	        m_eth_type_reg <= s_eth_type;
390	        m_ip_version_reg <= s_ip_version;
391	        m_ip_ihl_reg <= s_ip_ihl;
392	        m_ip_dscp_reg <= s_ip_dscp;
393	        m_ip_ecn_reg <= s_ip_ecn;
394	        m_ip_length_reg <= s_udp_length + 20;
395	        m_ip_identification_reg <= s_ip_identification;
396	        m_ip_flags_reg <= s_ip_flags;
397	        m_ip_fragment_offset_reg <= s_ip_fragment_offset;
398	        m_ip_ttl_reg <= s_ip_ttl;
399	        m_ip_protocol_reg <= s_ip_protocol;
400	        m_ip_header_checksum_reg <= s_ip_header_checksum;
401	        m_ip_source_ip_reg <= s_ip_source_ip;
402	        m_ip_dest_ip_reg <= s_ip_dest_ip;
403	        udp_source_port_reg <= s_udp_source_port;
404	        udp_dest_port_reg <= s_udp_dest_port;
405	        udp_length_reg <= s_udp_length;
406	        udp_checksum_reg <= s_udp_checksum;
407	    end
408	
409	    if (store_last_word) begin
410	        last_word_data_reg <= m_ip_payload_axis_tdata_int;
411	    end
412	end
413	
414	// output datapath logic
415	reg [7:0] m_ip_payload_axis_tdata_reg = 8'd0;
416	reg       m_ip_payload_axis_tvalid_reg = 1'b0, m_ip_payload_axis_tvalid_next;
417	reg       m_ip_payload_axis_tlast_reg = 1'b0;
418	reg       m_ip_payload_axis_tuser_reg = 1'b0;
419	
420	reg [7:0] temp_m_ip_payload_axis_tdata_reg = 8'd0;
421	reg       temp_m_ip_payload_axis_tvalid_reg = 1'b0, temp_m_ip_payload_axis_tvalid_next;
422	reg       temp_m_ip_payload_axis_tlast_reg = 1'b0;
423	reg       temp_m_ip_payload_axis_tuser_reg = 1'b0;
424	
425	// datapath control
426	reg store_ip_payload_int_to_output;
427	reg store_ip_payload_int_to_temp;
428	reg store_ip_payload_axis_temp_to_output;
429	
430	assign m_ip_payload_axis_tdata = m_ip_payload_axis_tdata_reg;
431	assign m_ip_payload_axis_tvalid = m_ip_payload_axis_tvalid_reg;
432	assign m_ip_payload_axis_tlast = m_ip_payload_axis_tlast_reg;
433	assign m_ip_payload_axis_tuser = m_ip_payload_axis_tuser_reg;
434	
435	// enable ready input next cycle if output is ready or if both output registers are empty
436	assign m_ip_payload_axis_tready_int_early = m_ip_payload_axis_tready || (!temp_m_ip_payload_axis_tvalid_reg && !m_ip_payload_axis_tvalid_reg);
437	
438	always @* begin
439	    // transfer sink ready state to source
440	    m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_reg;
441	    temp_m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
442	
443	    store_ip_payload_int_to_output = 1'b0;
444	    store_ip_payload_int_to_temp = 1'b0;
445	    store_ip_payload_axis_temp_to_output = 1'b0;
446	    
447	    if (m_ip_payload_axis_tready_int_reg) begin
448	        // input is ready
449	        if (m_ip_payload_axis_tready || !m_ip_payload_axis_tvalid_reg) begin
450	            // output is ready or currently not valid, transfer data to output
451	            m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
452	            store_ip_payload_int_to_output = 1'b1;
453	        end else begin
454	            // output is not ready, store input in temp
455	            temp_m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
456	            store_ip_payload_int_to_temp = 1'b1;
457	        end
458	    end else if (m_ip_payload_axis_tready) begin
459	        // input is not ready, but output is ready
460	        m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
461	        temp_m_ip_payload_axis_tvalid_next = 1'b0;
462	        store_ip_payload_axis_temp_to_output = 1'b1;
463	    end
464	end
465	
466	always @(posedge clk) begin
467	    m_ip_payload_axis_tvalid_reg <= m_ip_payload_axis_tvalid_next;
468	    m_ip_payload_axis_tready_int_reg <= m_ip_payload_axis_tready_int_early;
469	    temp_m_ip_payload_axis_tvalid_reg <= temp_m_ip_payload_axis_tvalid_next;
470	
471	    // datapath
472	    if (store_ip_payload_int_to_output) begin
473	        m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
474	        m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
475	        m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
476	    end else if (store_ip_payload_axis_temp_to_output) begin
477	        m_ip_payload_axis_tdata_reg <= temp_m_ip_payload_axis_tdata_reg;
478	        m_ip_payload_axis_tlast_reg <= temp_m_ip_payload_axis_tlast_reg;
479	        m_ip_payload_axis_tuser_reg <= temp_m_ip_payload_axis_tuser_reg;
480	    end
481	
482	    if (store_ip_payload_int_to_temp) begin
483	        temp_m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
484	        temp_m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
485	        temp_m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
486	    end
487	
488	    if (rst) begin
489	        m_ip_payload_axis_tvalid_reg <= 1'b0;
490	        m_ip_payload_axis_tready_int_reg <= 1'b0;
491	        temp_m_ip_payload_axis_tvalid_reg <= 1'b0;
492	    end
493	end
494	
495	endmodule
496	
497	`resetall
498

